<?php
namespace App\Livewire;use App\Models\GradingScale;use Illuminate\Support\Facades\Auth;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class GradingScales extends Component{public string $minimum='',$maximum='',$grade='',$remark='';public function add():void{$this->validate(['minimum'=>'required|numeric|min:0|max:100','maximum'=>'required|numeric|min:0|max:100|gte:minimum','grade'=>'required|string|max:10','remark'=>'nullable|string|max:255']);GradingScale::updateOrCreate(['school_id'=>Auth::user()->school_id,'grade'=>$this->grade],['minimum_percentage'=>$this->minimum,'maximum_percentage'=>$this->maximum,'remark'=>$this->remark?:null]);$this->reset(['minimum','maximum','grade','remark']);session()->flash('status','Grade scale saved.');}public function delete(int $id):void{GradingScale::where('school_id',Auth::user()->school_id)->findOrFail($id)->delete();session()->flash('status','Grade scale removed.');}public function render(){return view('livewire.grading-scales',['scales'=>GradingScale::where('school_id',Auth::user()->school_id)->orderByDesc('minimum_percentage')->get(),'pageTitle'=>'Grading Scales']);}}
